function diagnoseCsv(text: string): CsvDiagnostics { const lines = text.replace(/^\uFEFF/, "").split(/\r?\n/).map((line) => line.trim()).filter(Boolean); const split = (line: string) => line.split(",").map((cell) => cell.trim().replace(/^"|"$/g, "")); const preview = lines.slice(0, 6).map(split); const errors: string[] = []; if (!lines.length) return { preview, errors: ["CSVにデータがありません。"] }; const headers = split(lines[0]).map((value) => value.toLowerCase()); const nameIndex = headers.findIndex((value) => ["name", "馬名", "horse"].includes(value)); if (nameIndex < 0) errors.push("1行目: name / 馬名 / horse 列がありません。"); const numericKeys = ["speed", "stamina", "start", "form", "popularity", "starts", "wins", "seconds", "thirds", "avgfinish", "goodrate", "softrate", "heavyrate", "badrate"]; lines.slice(1).forEach((line, rowIndex) => { const row = split(line); const lineNo = rowIndex + 2; if (row.length < headers.length) errors.push(`${lineNo}行目: 列数が不足しています（${row.length}/${headers.length}列）。`); if (nameIndex >= 0 && !row[nameIndex]) errors.push(`${lineNo}行目: 馬名が空です。`); headers.forEach((header, index) => { if (numericKeys.includes(header) && row[index] !== "" && !Number.isFinite(Number(row[index]))) errors.push(`${lineNo}行目: ${header} は数値で入力してください。`); }); const styleIndex = headers.findIndex((value) => ["style", "脚質"].includes(value)); if (styleIndex >= 0 && row[styleIndex] && !["逃げ", "先行", "差し", "追込"].includes(row[styleIndex])) errors.push(`${lineNo}行目: 脚質は「逃げ・先行・差し・追込」のいずれかです。`); }); return { preview, errors }; }

function getBranches(horses: Horse[], pace: string): Branch[] {
  const total = Math.max(1, horses.length); const frontShare = horses.filter((horse) => horse.style === "逃げ" || horse.style === "先行").length / total; const backShare = horses.filter((horse) => horse.style === "追込").length / total;
  const base = pace === "スロー" ? [52, 32, 16] : pace === "ハイ" ? [18, 48, 34] : [34, 43, 23];
  const values = [base[0] + frontShare * 14 - backShare * 7, base[1] + backShare * 8, base[2] + backShare * 15 - frontShare * 8]; const sum = values.reduce((a, b) => a + b, 0);
  const factors = [{ 逃げ: 1.035, 先行: 1.02, 差し: .985, 追込: .96 }, { 逃げ: .985, 先行: .995, 差し: 1.02, 追込: 1.01 }, { 逃げ: .96, 先行: .97, 差し: 1.015, 追込: 1.045 }];
  return [{ key: "front", label: "前残り", summary: "先行勢が隊列の利を活かす分岐", styles: "逃げ・先行", probability: values[0] / sum * 100, factors: factors[0] as Record<Style, number> }, { key: "middle", label: "差し浮上", summary: "中団から直線で順位を上げる分岐", styles: "差し", probability: values[1] / sum * 100, factors: factors[1] as Record<Style, number> }, { key: "back", label: "後方一気", summary: "持久力のある追込勢が届く分岐", styles: "追込・差し", probability: values[2] / sum * 100, factors: factors[2] as Record<Style, number> }];
}

function getBranchRankings(branches: Branch[], results: ResultHorse[]): BranchRanking[] { return branches.map((branch) => { const scored = results.map((horse) => { const branchScore = horse.avgScore * branch.factors[horse.style]; const top3Chance = clamp(horse.placeRate * branch.factors[horse.style] * (1 + branch.probability / 200)); return { ...horse, branchScore, top3Chance }; }).sort((a, b) => b.branchScore - a.branchScore); return { branch, horses: scored }; }); }

function runSimulation(horses: Horse[], distance: number, going: Going, pace: string, runs: number, seed: number, branches: Branch[], manualAdjustments: Record<number, number> = {}) {
  const paceFactor: Record<string, Record<Style, number>> = { スロー: { 逃げ: 1.045, 先行: 1.025, 差し: .98, 追込: .95 }, 平均: { 逃げ: 1, 先行: 1, 差し: 1, 追込: 1 }, ハイ: { 逃げ: .94, 先行: .97, 差し: 1.025, 追込: 1.06 } };
  const distanceRatio = clamp((distance - 1600) / 1200, 0, 1); const hash = (value: number) => { const x = Math.sin(value * 12.9898 + 78.233) * 43758.5453; return x - Math.floor(x); }; const totals = horses.map((horse) => ({ ...horse, wins: 0, places: 0, avgScore: 0, historyAdjustment: 0 }));
  for (let i = 0; i < runs; i++) { const branchRoll = hash(seed * 1000003 + i * 7919); let cumulative = 0; const branch = branches.find((candidate) => { cumulative += candidate.probability / 100; return branchRoll <= cumulative; }) || branches[0]; totals.map((horse) => { const distanceFit = horse.speed * (1 - distanceRatio) + horse.stamina * distanceRatio; const goingFit = .88 + horse.goingRates[going] / 100 * .12; const pastWinRate = horse.starts ? horse.winsPast / horse.starts * 100 : 0; const pastTop3Rate = horse.starts ? (horse.winsPast + horse.secondsPast + horse.thirdsPast) / horse.starts * 100 : 0; const confidence = Math.min(1, horse.starts / 20); const historyAdjustment = ((pastWinRate - 18) * .075 + (pastTop3Rate - 52) * .025 + (68 - horse.avgFinish) * .12) * confidence + (manualAdjustments[horse.no] ?? 0); const paceFit = paceFactor[pace][horse.style] * branch.factors[horse.style]; const noise = ((hash(seed * 37 + i * 97 + horse.no * 53) + hash(seed * 7919 + i * 17 + horse.no * 131)) - 1) * 9; const score = (horse.speed * .28 + horse.stamina * .23 + horse.start * .12 + horse.form * .22 + distanceFit * .08 + historyAdjustment) * paceFit * goingFit + noise; return { horse, score, historyAdjustment }; }).sort((a, b) => b.score - a.score).forEach((item, index) => { item.horse.avgScore += item.score; item.horse.historyAdjustment = item.historyAdjustment; if (index === 0) item.horse.wins++; if (index < 3) item.horse.places++; }); }
  return totals.map((horse) => { const winRate = horse.wins / runs * 100; const standardError = Math.sqrt(Math.max(.0001, (winRate / 100) * (1 - winRate / 100)) / runs) * 100; return { ...horse, winRate, placeRate: horse.places / runs * 100, avgScore: horse.avgScore / runs, uncertaintyLow: clamp(winRate - 1.96 * standardError), uncertaintyHigh: clamp(winRate + 1.96 * standardError), historyAdjustment: horse.historyAdjustment }; }).sort((a, b) => b.winRate - a.winRate) as ResultHorse[];
}

